package runtime

import (
	"crypto/rand"
	"crypto/rsa"
	"crypto/tls"
	"crypto/x509"
	"crypto/x509/pkix"
	"fmt"
	"math/big"
	"net"
	"time"

	"github.com/go-mysql-org/go-mysql/mysql"
	"github.com/go-mysql-org/go-mysql/server"

	"lustre/internal/audit"
	"lustre/internal/upstream"
)

// selfSignedCertLifetime is how long the in-memory certificate generated by
// newSelfSignedTLSConfig claims to be valid for. It is generated fresh on
// every process start and never persisted, so this only has to outlast a
// single run of the proxy — it is not a real PKI lifetime decision.
const selfSignedCertLifetime = 10 * 365 * 24 * time.Hour

// newSelfSignedTLSConfig generates a throwaway self-signed certificate,
// backed by rsaKey, and wraps it in a *tls.Config for the handshake server.
//
// Nothing here is meant to prove the proxy's identity to a client the way a
// real certificate would — go-mysql's default client behaviour (see
// newHandshakeServer) never checks it, and nothing here asks the client to.
// It exists purely so the server can offer CLIENT_SSL at all: go-mysql
// requires a *tls.Config with at least one certificate before it will
// advertise that capability flag in the handshake packet, regardless of
// whether the certificate would pass real verification.
func newSelfSignedTLSConfig(rsaKey *rsa.PrivateKey) (*tls.Config, error) {
	serialLimit := new(big.Int).Lsh(big.NewInt(1), 128)
	serial, err := rand.Int(rand.Reader, serialLimit)
	if err != nil {
		return nil, fmt.Errorf("generate certificate serial number: %w", err)
	}

	template := &x509.Certificate{
		SerialNumber: serial,
		Subject:      pkix.Name{CommonName: "lustre-proxy"},
		NotBefore:    time.Now(),
		NotAfter:     time.Now().Add(selfSignedCertLifetime),
		KeyUsage:     x509.KeyUsageKeyEncipherment | x509.KeyUsageDigitalSignature,
		ExtKeyUsage:  []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth},
	}

	der, err := x509.CreateCertificate(rand.Reader, template, template, &rsaKey.PublicKey, rsaKey)
	if err != nil {
		return nil, fmt.Errorf("create self-signed certificate: %w", err)
	}

	cert := tls.Certificate{
		Certificate: [][]byte{der},
		PrivateKey:  rsaKey,
	}

	return &tls.Config{Certificates: []tls.Certificate{cert}}, nil
}

// newHandshakeMaterial generates the key pair and self-signed TLS
// configuration the client-facing handshake is built from.
//
// The proxy no longer checks passwords, so caching_sha2_password's RSA key
// exchange is never used, but the TLS certificate is still required: a stock
// MySQL client (ssl-mode=PREFERRED, the default) only sends its password
// over TLS, and refuses to continue on a plaintext connection with
//
//	ERROR 2061 (HY000): Authentication plugin 'caching_sha2_password' reported error: Authentication requires secure connection.
//
// before a single authentication packet reaches the proxy. Pass-through
// authentication also requires the client leg to be TLS (see
// passthrough.Provider), since the client's cleartext password answer is
// relayed to the database as it is. The certificate is self-signed and
// generated in memory fresh on every process start; its only job is to let
// TLS start, not to vouch for the server's identity to a client that (by
// default) never checks it.
//
// Clients are offered caching_sha2_password first because it is MySQL 8's
// default plugin and the only one MySQL 9 clients still ship: a client built
// against mysql_native_password refuses to even try a server that offers
// only that. Whichever plugin the user's account really uses, the database
// then names it in the challenge the proxy relays.
func newHandshakeMaterial() (*rsa.PrivateKey, *tls.Config, error) {
	rsaKey, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		return nil, nil, fmt.Errorf("generate RSA key for the client handshake: %w", err)
	}
	tlsConfig, err := newSelfSignedTLSConfig(rsaKey)
	if err != nil {
		return nil, nil, fmt.Errorf("generate self-signed TLS config: %w", err)
	}
	return rsaKey, tlsConfig, nil
}

// newHandshakeServerFor builds the go-mysql server for one client connection,
// authenticating through provider. Building it per connection is cheap (the
// key material is shared) and is what lets the provider carry that
// connection's own state.
func newHandshakeServerFor(rsaKey *rsa.PrivateKey, tlsConfig *tls.Config, provider server.AuthenticationProvider) *server.Server {
	return server.NewServerWithAuth("8.0.11", mysql.DEFAULT_COLLATION_ID, mysql.AUTH_CACHING_SHA2_PASSWORD, rsaKey, tlsConfig, provider)
}

func (p *Proxy) configureUpstreamTLS() error {
	host, _, err := net.SplitHostPort(p.UpstreamAddr)
	if err != nil {
		return fmt.Errorf("upstream address: %w", err)
	}
	p.upstreamTLS, err = upstream.TLSConfig(host, p.TLS, p.TLSCAFile)
	if err != nil {
		return fmt.Errorf("server %q: %w", p.UpstreamName, err)
	}
	if p.TLS == audit.TLSSkipVerify {
		p.Logger.Printf("WARNING: server %q uses tls=skip-verify; certificate verification disabled (development only)", p.UpstreamName)
	}
	return nil
}

// UpdateUpstreamTLS atomically replaces this proxy's upstream connection
// details *and* its TLS settings. The new TLS configuration is built — which
// validates the mode and reads and parses any CA file — for the new address's
// own host before anything is swapped, so:
//
//   - a changed host gets a certificate check against that host, not the
//     original one;
//   - a change of mode (skip-verify to verify, say) or of CA file really takes
//     effect for new connections, instead of being reported as applied while
//     the old verification stays in force;
//   - if the new settings are invalid (an unreadable CA file, an unknown
//     mode), it returns an error and changes nothing: the last good
//     configuration keeps serving new connections.
//
// user and pass are the bootstrap account (see upstreamConfig.User): clients
// log in as themselves, so changing them changes nothing about who may
// connect, only which account new connections open the database link with.
//
// Like UpdateUpstream it only affects sessions accepted after it returns;
// a session in flight keeps the upstreamConfig — TLS included — it captured.
func (p *Proxy) UpdateUpstreamTLS(addr, name, user, pass, tlsMode, caFile string) error {
	host, _, err := net.SplitHostPort(addr)
	if err != nil {
		return fmt.Errorf("upstream address: %w", err)
	}
	tlsCfg, err := upstream.TLSConfig(host, tlsMode, caFile)
	if err != nil {
		return fmt.Errorf("server %q: %w", name, err)
	}

	p.upstream.Store(&upstreamConfig{
		Addr:      addr,
		Name:      name,
		User:      user,
		Pass:      pass,
		TLS:       tlsCfg,
		TLSMode:   tlsMode,
		TLSCAFile: caFile,
	})

	if tlsMode == audit.TLSSkipVerify && p.Logger != nil {
		p.Logger.Printf("WARNING: server %q uses tls=skip-verify; certificate verification disabled (development only)", name)
	}
	return nil
}
